code_sketch:
pthread_mutex_lock(&mutex);
int rc = -1;
Entry *e = table_find_or_create(key);     /* may fail           */
if (e == NULL) goto out;                  /* unlock happens once */
e->hits++;
rc = 0;
out:
pthread_mutex_unlock(&mutex);             /* every path passes here */
return rc;

